use std::io::{self,BufRead};use std::collections::BTreeSet;#[derive(Clone)]enum Json{Null,Bool(bool),Num(i64),Str(String),Arr(Vec<Json>),Obj(Vec<(String,Json)>)}struct Parser<'a>{s:&'a[u8],i:usize}impl<'a>Parser<'a>{fn new(s:&'a[u8])->Self{Parser{s,i:0}}fn parse(&mut self)->Result<Json,()>{self.skip_ws();let v=self.parse_value()?;self.skip_ws();if self.i!=self.s.len(){return Err(())}Ok(v)}fn skip_ws(&mut self){while self.i<self.s.len(){match self.s[self.i]{b' '|10|13|9=>self.i+=1,_=>break}}}fn parse_value(&mut self)->Result<Json,()>{self.skip_ws();if self.i>=self.s.len(){return Err(())}match self.s[self.i]{110=>{if self.s.get(self.i..self.i+4)==Some(b"null"){self.i+=4;Ok(Json::Null)}else{Err(())}}116=>{if self.s.get(self.i..self.i+4)==Some(b"true"){self.i+=4;Ok(Json::Bool(true))}else{Err(())}}102=>{if self.s.get(self.i..self.i+5)==Some(b"false"){self.i+=5;Ok(Json::Bool(false))}else{Err(())}}34=>{let s=self.parse_string()?;Ok(Json::Str(s))}91=>self.parse_array(),123=>self.parse_object(),45|48..=57=>self.parse_number(),_=>Err(())}}fn parse_number(&mut self)->Result<Json,()>{let start=self.i;if self.s[self.i]==45{self.i+=1}while self.i<self.s.len()&&self.s[self.i].is_ascii_digit(){self.i+=1}let slice=&self.s[start..self.i];let s=std::str::from_utf8(slice).map_err(|_|())?;let n:i64=s.parse().map_err(|_|())?;Ok(Json::Num(n))}fn parse_string(&mut self)->Result<String,()>{if self.s[self.i]!=34{return Err(())}self.i+=1;let mut buf=Vec::new();while self.i<self.s.len(){let b=self.s[self.i];self.i+=1;if b==34{return String::from_utf8(buf).map_err(|_|())}else if b==92{if self.i>=self.s.len(){return Err(())}let e=self.s[self.i];self.i+=1;match e{34=>buf.push(34),92=>buf.push(92),47=>buf.push(47),98=>buf.push(8),102=>buf.push(12),110=>buf.push(10),114=>buf.push(13),116=>buf.push(9),117=>{let mut cp:u32=0;for _ in 0..4{if self.i>=self.s.len(){return Err(())}let h=self.s[self.i];self.i+=1;let v=match h{48..=57=>(h-48)as u32,97..=102=>(h-97+10)as u32,65..=70=>(h-65+10)as u32,_=>return Err(())};cp=cp*16+v}if cp>=0xD800&&cp<=0xDBFF{if self.i+1<self.s.len()&&self.s[self.i]==92&&self.s[self.i+1]==117{self.i+=2;let mut low:u32=0;for _ in 0..4{if self.i>=self.s.len(){return Err(())}let h=self.s[self.i];self.i+=1;let v=match h{48..=57=>(h-48)as u32,97..=102=>(h-97+10)as u32,65..=70=>(h-65+10)as u32,_=>return Err(())};low=low*16+v}let c=0x10000+((cp-0xD800)<<10)+(low-0xDC00);if let Some(ch)=char::from_u32(c){let mut b=[0u8;4];let s=ch.encode_utf8(&mut b);buf.extend_from_slice(s.as_bytes())}else{return Err(())}}else{return Err(())}}else{if let Some(ch)=char::from_u32(cp){let mut b=[0u8;4];let s=ch.encode_utf8(&mut b);buf.extend_from_slice(s.as_bytes())}else{return Err(())}}}_=>return Err(())}}else{buf.push(b)}}Err(())}fn parse_array(&mut self)->Result<Json,()>{self.i+=1;let mut arr=Vec::new();self.skip_ws();if self.i<self.s.len()&&self.s[self.i]==93{self.i+=1;return Ok(Json::Arr(arr))}loop{let v=self.parse_value()?;arr.push(v);self.skip_ws();if self.i>=self.s.len(){return Err(())}if self.s[self.i]==44{self.i+=1;continue}else if self.s[self.i]==93{self.i+=1;break}else{return Err(())}}Ok(Json::Arr(arr))}fn parse_object(&mut self)->Result<Json,()>{self.i+=1;let mut obj=Vec::new();self.skip_ws();if self.i<self.s.len()&&self.s[self.i]==125{self.i+=1;return Ok(Json::Obj(obj))}loop{self.skip_ws();if self.i>=self.s.len()||self.s[self.i]!=34{return Err(())}let key=self.parse_string()?;self.skip_ws();if self.i>=self.s.len()||self.s[self.i]!=58{return Err(())}self.i+=1;let val=self.parse_value()?;obj.push((key,val));self.skip_ws();if self.i>=self.s.len(){return Err(())}if self.s[self.i]==44{self.i+=1;continue}else if self.s[self.i]==125{self.i+=1;break}else{return Err(())}}obj.sort_by(|a,b|a.0.cmp(&b.0));Ok(Json::Obj(obj))}}enum Change{Add{path:String,value:Json},Remove{path:String,value:Json},Replace{path:String,before:Json,after:Json}}fn escape_key(k:&str)->String{let mut s=String::new();for c in k.chars(){if c==126{s.push(126);s.push(48)}else if c==47{s.push(126);s.push(49)}else{s.push(c)}}s}fn diff(a:&Json,b:&Json,path:&str,changes:&mut Vec<Change>){match(a,b){(Json::Null,Json::Null)=>{},(Json::Bool(x),Json::Bool(y))=>{if x!=y{changes.push(Change::Replace{path:path.to_string(),before:a.clone(),after:b.clone()})}},(Json::Num(x),Json::Num(y))=>{if x!=y{changes.push(Change::Replace{path:path.to_string(),before:a.clone(),after:b.clone()})}},(Json::Str(x),Json::Str(y))=>{if x!=y{changes.push(Change::Replace{path:path.to_string(),before:a.clone(),after:b.clone()})}},(Json::Arr(x),Json::Arr(y))=>{let n=x.len().min(y.len());for i in 0..n{let mut p=String::from(path);p.push(47);p.push_str(&i.to_string());diff(&x[i],&y[i],&p,changes)}if x.len()>y.len(){for i in y.len()..x.len(){let mut p=String::from(path);p.push(47);p.push_str(&i.to_string());changes.push(Change::Remove{path:p,value:x[i].clone()})}}else if y.len()>x.len(){for i in x.len()..y.len(){let mut p=String::from(path);p.push(47);p.push_str(&i.to_string());changes.push(Change::Add{path:p,value:y[i].clone()})}}},(Json::Obj(x),Json::Obj(y))=>{let mut keys:BTreeSet<&str>=BTreeSet::new();for(k,_)in x{keys.insert(k);}for(k,_)in y{keys.insert(k);}for k in keys{let av=x.iter().find(|(kk,_)|kk==k).map(|(_,v)|v);let bv=y.iter().find(|(kk,_)|kk==k).map(|(_,v)|v);let mut p=String::from(path);p.push(47);p.push_str(&escape_key(k));match(av,bv){(Some(a),Some(b))=>diff(a,b,&p,changes),(Some(a),None)=>changes.push(Change::Remove{path:p,value:a.clone()}),(None,Some(b))=>changes.push(Change::Add{path:p,value:b.clone()}),(None,None)=>{}}}},_=>{changes.push(Change::Replace{path:path.to_string(),before:a.clone(),after:b.clone()})}}}fn write_json_str(s:&str,out:&mut String){out.push(34);for c in s.chars(){match c{34=>{out.push(92);out.push(34)},92=>{out.push(92);out.push(92)},10=>{out.push(92);out.push(110)},13=>{out.push(92);out.push(114)},9=>{out.push(92);out.push(116)},c if c<=' '=>{out.push(92);out.push(117);for shift in[12,8,4,0]{let d=(c as u32>>shift)&0xF;out.push(char::from_digit(d,16).unwrap())}},_=>out.push(c)}}out.push(34)}fn push_hex4(out:&mut String,v:u32){for shift in[12,8,4,0]{let d=(v>>shift)&0xF;out.push(char::from_digit(d,16).unwrap())}}fn write_json(v:&Json,out:&mut String){match v{Json::Null=>out.push_str("null"),Json::Bool(b)=>out.push_str(if*b{"true"}else{"false"}),Json::Num(n)=>out.push_str(&n.to_string()),Json::Str(s)=>write_json_str(s,out),Json::Arr(a)=>{out.push(91);for(i,v)in a.iter().enumerate(){if i>0{out.push(44)}write_json(v,out)}out.push(93)},Json::Obj(o)=>{out.push(123);for(i,(k,v))in o.iter().enumerate(){if i>0{out.push(44)}write_json_str(k,out);out.push(58);write_json(v,out)}out.push(125)}}}fn write_change(c:&Change,out:&mut String){out.push(123);match c{Change::Add{path,value}=>{out.push_str("\"op\":\"add\",\"path\":");write_json_str(path,out);out.push_str(",\"value\":");write_json(value,out)},Change::Remove{path,value}=>{out.push_str("\"op\":\"remove\",\"path\":");write_json_str(path,out);out.push_str(",\"value\":");write_json(value,out)},Change::Replace{path,before,after}=>{out.push_str("\"op\":\"replace\",\"path\":");write_json_str(path,out);out.push_str(",\"before\":");write_json(before,out);out.push_str(",\"after\":");write_json(after,out)}}out.push(125)}fn main(){let stdin=io::stdin();for line in stdin.lock().lines(){let line=match line{Ok(l)=>l,Err(_)=>continue};let trimmed=line.trim();if trimmed.is_empty(){println!("INVALID_JSON");continue}let mut parser=Parser::new(trimmed.as_bytes());let val=match parser.parse(){Ok(v)=>v,Err(_)=>{println!("INVALID_JSON");continue}};let(before,after)=match val{Json::Obj(mut obj)=>{let mut before=None;let mut after=None;for(k,v)in obj.drain(..){if k=="before"{before=Some(v)}else if k=="after"{after=Some(v)}}match(before,after){(Some(b),Some(a))=>(b,a),_=>{println!("INVALID_JSON");continue}}},_=>{println!("INVALID_JSON");continue}};let mut changes=Vec::new();diff(&before,&after,"",&mut changes);let mut out=String::new();out.push(123);out.push_str("\"changes\":[");for(i,c)in changes.iter().enumerate(){if i>0{out.push(44)}write_change(c,&mut out)}out.push(93);out.push(125);println!("{}",out)}}
